    const s = document.createElement('style');
    s.id = 'sp-corner-style';
    s.textContent = `
      #sp-corner{position:fixed;left:14px;bottom:14px;z-index:2147482000;
        display:flex;flex-direction:column;align-items:flex-start;gap:8px}
