    run(force = false) {
      if (!state.enabled || !document.body) return;
      const vw = document.documentElement.clientWidth || window.innerWidth;
      const vh = window.innerHeight;
      const seen = new Set();
      const toPaint = [];

      for (const y of [6, 40, 90, 150, 210, 270]) {
        if (y > vh * 0.5) break;
        for (const x of [vw * 0.25, vw * 0.5, vw * 0.75]) {
