        }
        const bg = this.parse(cs.backgroundColor);
        if (
          bg &&
          bg.a > 0.5 &&
          this.lum(bg) > 0.75 &&
          r.width * r.height > 400
        ) {
          lightBg++;
          flagged.push({ el, color: "#ffb84d" });
        }
