            type: "button",
            text: "Preview",
            onclick: () => this.applyCSS(false),
          }),
          h("button", {
            class: "btn",
            type: "button",
            text: "Clear",
            onclick: () => {
              e.css.value = "";
              this.applyCSS(true);
            },
          }),
          h("button", {
            class: "btn",
            type: "button",
            text: "Copy base CSS",
            onclick: () => copyText(BASE_CSS),
          }),
        ),
        h("div", { class: "label", text: "Diagnostics" }),
        e.debug,
        h(
          "div",
          { class: "btns" },
          h("button", {
            class: "btn",
            type: "button",
            text: "Refresh",
            onclick: () => this.refreshDebug(),
          }),
          h("button", {
            class: "btn",
            type: "button",
            text: "Scan contrast",
            onclick: () => {
              const res = Contrast.scan();
              this.refreshDebug();
              this.toast(
                `${res.darkText} dark text · ${res.lightBg} light backgrounds (outlined)`,
                3000,
              );
            },
          }),
          h("button", {
            class: "btn",
            type: "button",
            text: "Clear marks",
            onclick: () => {
              Contrast.clear();
              Contrast.last = null;
              this.refreshDebug();
            },
          }),
          h("button", {
            class: "btn",
            type: "button",
            text: "Reset all settings",
            onclick: resetAll,
          }),
        ),
      );

      e.toast = h("div", {
        class: "toast",
        role: "status",
        "aria-live": "polite",
      });

      this.root.append(e.gear, e.menu, e.dev, e.toast);
    },

    sync() {
      if (!this.root) return;
      const e = this.el;
      this.host.style.setProperty("--accent", state.accentColor);
      e.darkSwitch.setAttribute("aria-checked", String(state.enabled));
      e.devSwitch.setAttribute("aria-checked", String(state.devMode));
      if (e.textColor.value !== state.textColor)
        e.textColor.value = state.textColor;
      if (e.accentColor.value !== state.accentColor)
        e.accentColor.value = state.accentColor;
      e.devOpen.hidden = !state.devMode;
      if (!e.dev.hidden) this.refreshDebug();
    },

    toggleMenu() {
      this.el.menu?.hidden ? this.openMenu() : this.closeMenu();
    },

    openMenu() {
      this.mount();
      if (!this.root) return;
      this.closeDev();
      this.el.menu.hidden = false;
      this.el.gear.setAttribute("aria-expanded", "true");
    },

    closeMenu() {
      if (!this.root) return;
      this.el.menu.hidden = true;
      this.el.gear.setAttribute("aria-expanded", "false");
    },

    openDev() {
      if (!this.root || !state.devMode) return;
      this.closeMenu();
      this.el.css.value = state.customCSS;
      this.el.dev.hidden = false;
      this.refreshDebug();
      this.el.css.focus();
    },

    closeDev() {
      if (this.root) this.el.dev.hidden = true;
    },

    applyCSS(persist) {
      state.customCSS = this.el.css.value;
      if (persist) Storage.save(KEYS.CUSTOM_CSS, state.customCSS);
      if (state.enabled) StyleManager.inject();
      this.refreshDebug();
      this.toast(persist ? "Custom CSS saved" : "Previewing (not saved)");
    },

    refreshDebug() {
      if (!this.root) return;
      const info = typeof GM_info !== "undefined" ? GM_info : null;
      const lines = [
        `Version        ${VERSION}`,
        `Dark mode      ${state.enabled ? "on" : "off"}`,
        `Stylesheet     ${document.getElementById(IDS.STYLE) ? "injected" : "not injected"}`,
        `Custom CSS     ${state.customCSS.trim() ? state.customCSS.length + " chars" : "none"}`,
        `Header fixes   ${document.querySelectorAll(`[${HEADER_ATTR}]`).length}`,
        `Text / accent  ${state.textColor} / ${state.accentColor}`,
        `Page           ${location.pathname}`,
        `Viewport       ${window.innerWidth} x ${window.innerHeight}`,
        `Manager        ${info ? `${info.scriptHandler || "?"} ${info.version || ""}` : "unknown"}`,
      ];
      if (Contrast.last) {
        lines.push(
          `Last scan      ${Contrast.last.darkText} dark text (red), ${Contrast.last.lightBg} light bg (orange), ${Contrast.last.checked} checked`,
        );
      }
      this.el.debug.textContent = lines.join("\n");
    },

    toast(message, ms = 1800) {
      if (!this.root) return;
      const t = this.el.toast;
      t.textContent = message;
      t.classList.add("show");
      clearTimeout(this.toastTimer);
      this.toastTimer = setTimeout(() => t.classList.remove("show"), ms);
    },
  };

  window.addEventListener(
    "keydown",
    (e) => {
      if (
        e.ctrlKey &&
        e.shiftKey &&
        !e.altKey &&
        !e.metaKey &&
        e.code === "KeyD"
      ) {
        e.preventDefault();
        e.stopPropagation();
        toggleDarkMode();
      } else if (e.key === "Escape" && UI.root) {
        UI.closeMenu();
        UI.closeDev();
      }
    },
    true,
  );

  if (typeof GM_registerMenuCommand === "function") {
    try {
      GM_registerMenuCommand("Toggle Pinterest Dark Mode (Ctrl+Shift+D)", () =>
        toggleDarkMode(),
      );
      GM_registerMenuCommand("Open Dark Mode settings", () => UI.openMenu());
    } catch (_) {}
  }

  if (typeof GM_addValueChangeListener === "function") {
    const follow = (key, update, restyle = true) => {
      try {
        GM_addValueChangeListener(key, (_name, _old, value, remote) => {
          if (!remote) return;
          update(value);
          if (restyle) StyleManager.apply();
          else UI.sync();
        });
      } catch (_) {}
    };
    follow(KEYS.ENABLED, (v) => {
      state.enabled = v !== false;
    });
    follow(KEYS.TEXT_COLOR, (v) => {
      state.textColor = cleanColor(v, DEFAULTS.TEXT);
    });
    follow(KEYS.ACCENT_COLOR, (v) => {
      state.accentColor = cleanColor(v, DEFAULTS.ACCENT);
    });
    follow(KEYS.CUSTOM_CSS, (v) => {
      state.customCSS = typeof v === "string" ? v : "";
    });
    follow(
      KEYS.DEV_MODE,
      (v) => {
        state.devMode = v === true;
        if (!state.devMode) UI.closeDev();
      },
      false,
    );
  }

  function startObservers() {
    new MutationObserver(() => {
      if (
        state.enabled &&
        !document.documentElement.classList.contains(DARK_CLASS)
      ) {
        document.documentElement.classList.add(DARK_CLASS);
      }
    }).observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    let pending = false;
    new MutationObserver(() => {
      if (pending) return;
      pending = true;
      setTimeout(() => {
        pending = false;
        StyleManager.ensure();
        HeaderFixer.schedule();
        UI.mount();
      }, 250);
    }).observe(document.body, { childList: true, subtree: true });

    let scrollPending = false;
    window.addEventListener(
      "scroll",
      () => {
        if (!state.enabled || scrollPending) return;
        scrollPending = true;
        setTimeout(() => {
          scrollPending = false;
          HeaderFixer.schedule();
        }, 150);
      },
      { passive: true },
    );

    window.addEventListener("resize", () => HeaderFixer.schedule(true), {
      passive: true,
    });
    window.addEventListener("load", () => HeaderFixer.schedule(true), {
      once: true,
    });
  }

  function showWelcome() {
    try {
      if (sessionStorage.getItem("tm-pdm-notice")) return;
      sessionStorage.setItem("tm-pdm-notice", "1");
    } catch (_) {}
    if (state.enabled)
      UI.toast(
        `Pinterest Dark Mode But Better v${VERSION} active · Ctrl+Shift+D to toggle`,
        3500,
      );
  }

  StyleManager.apply();

  function onReady() {
    UI.mount();
    startObservers();
    HeaderFixer.schedule(true);
    showWelcome();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", onReady, { once: true });
  } else {
    onReady();
  }
})();

