// ---------------- 15. 不挂 DOM 的 new Audio() 也能盯上 + 切歌指令 ----------------
{
  const dQ = new JSDOM('<!doctype html><html><head></head><body></body></html>', {
    runScripts: 'dangerously',
    pretendToBeVisual: true,
    url: 'https://iirose.com/',
  });
