try {
  ({ JSDOM } = await import('jsdom'));
} catch {
  // 宁可红也别静默跳过：跳过会让人以为「测试全绿」，其实这一整套没跑。
  console.error('缺少 jsdom：先跑 npm install（jsdom 已写进 devDependencies）');
  process.exit(1);
}

const failures = [];
const check = (label, cond, extra = '') => {
  console.log((cond ? '  ok   ' : '  FAIL ') + label + (extra ? '  ' + extra : ''));
  if (!cond) failures.push(label);
};

const dom = new JSDOM('<!doctype html><html><head></head><body><div id="host"></div></body></html>', {
  // getInternalVMContext() 要求显式允许脚本执行（jsdom >= 16 行为）；
  // outside-only 只允许我们用 vm 手动注入，页面自身不执行任何脚本。
  runScripts: 'outside-only',
  pretendToBeVisual: true,
  url: 'http://127.0.0.1:3080/',
});
const { window } = dom;
// jsdom 没实现媒体播放：本地试听分支会调 load()/play()，补成空实现（否则刷一屏 "Not implemented"）
window.HTMLMediaElement.prototype.load = function () {};
window.HTMLMediaElement.prototype.play = function () {
  return Promise.resolve();
};
window.HTMLMediaElement.prototype.pause = function () {};
const { document } = window;
