const EQUAL = [
  'artifact.bytes', 'artifact.comments', 'artifact.srcBytes',
  'pages.overview.stats', 'pages.overview.points', 'pages.overview.activity',
  'pages.projects.projects', 'pages.projects.rows',
  'pages.ranking.ranking', 'pages.ranking.rows',
