  const warnTabs = Array.from(rootEl.querySelectorAll('.mk-tab.mk-warn')).map((b) => b.textContent);
  check('网易云检查失败后 tab 亮红点', warnTabs.some((t) => /网易云/.test(t)), JSON.stringify(warnTabs));
  check(
