//
// ── 用法 ──────────────────────────────────────────────────────────────
//  A. 油猴：装脚本 → 打开 https://aisese.ai 并登录 → 右下角「AI妄想导出」面板
//     → 粘贴卡片地址（https://aisese.ai/discovery/{sid}）→ 导出。
//  B. 不用油猴：登录后 F12 控制台整段粘贴本文件回车。
//
// ── 逆向结论（实测）─────────────────────────────────────────────────
//  站点：QuackAI 架构的「云酒馆」，卡片是完整内容（不是摘要）。
//  鉴权：localStorage.authToken → 请求头 Authorization: Bearer <token>
//        另需 X-App-Platform: web，否则连接会被重置
//  详情：GET /api/v1/studioCard/info?sid={sid}      ← 一次拿全，无需二次请求
//        → { name, authorName, tags, intro, cover, baseTokenCount,
//            charList:[{ name, prompt, intro, attrs:[{key,value}], customAttrs }],
//            prologue:{ greetings:[{ key,title,value }] },
//            characterbooks:[{ bid, name, entryList:[{ content, triggerKeywords,
//                              enabled, constant, position, depth }] }],
//            prompts:{ characterFineTunePrompt, characterGenerationPrompt } }
//  页面：https://aisese.ai/discovery/{sid}
//  列表：DOM 上每张卡带 data-character-id 属性
//
// ── 数据模型提醒 ────────────────────────────────────────────────────
//  charList[0].prompt 全站为空，角色设定走结构化表单（attrs 10 槽位）+
//  customAttrs + 开场白 + 世界书；description 由这些字段拼装而来。
//
(function () {
  'use strict';
  if (window.__ASE_LOADED__) { console.warn('[AI妄想导出] 已加载'); return; }
  window.__ASE_LOADED__ = true;

  const LOG = (...a) => console.log('%c[AI妄想导出]', 'color:#5b8def;font-weight:700', ...a);
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  /* ============ 1. 基础 ============ */
  function parseSid(input) {
    if (!input) return null;
    const s = String(input).trim();
    if (/^[A-Za-z0-9_-]{15,32}$/.test(s)) return s;
    let m = s.match(/\/(?:discovery|character|chat|studioCard)\/([A-Za-z0-9_-]{15,32})/);
    if (m) return m[1];
    m = s.match(/[?&](?:sid|id|characterId)=([A-Za-z0-9_-]{15,32})/);
    if (m) return m[1];
    m = s.match(/\/([A-Za-z0-9_-]{15,32})\/?(?:[?#]|$)/);
    return m ? m[1] : null;
  }

  const getToken = () => localStorage.getItem('authToken') || '';

  async function fetchCard(sid) {
    const tk = getToken();
    if (!tk) {
      const e = new Error('未登录：localStorage 里没有 authToken。请先登录 aisese.ai。');
      e.code = 401;
      throw e;
    }
    const r = await fetch('/api/v1/studioCard/info?sid=' + encodeURIComponent(sid), {
      headers: { 'X-App-Platform': 'web', 'Authorization': 'Bearer ' + tk, 'Accept': 'application/json' },
      credentials: 'include',
    });
    const t = await r.text();
    let j = null;
    try { j = JSON.parse(t); } catch (e) { /* ignore */ }
    if (r.status === 401 || r.status === 403) {
      const e = new Error('鉴权失败（' + r.status + '）：登录可能已过期，请重新登录 aisese.ai。');
      e.code = r.status;
      throw e;
    }
    if (!j || j.code !== 0 || !j.data) {
      throw new Error('接口返回异常：HTTP ' + r.status + ' ' + (t.slice(0, 160) || '(空)'));
    }
    return j.data;
  }

  /* ---- 提示词预设：全站统一的系统提示词体系 ---- */
  async function fetchPresets() {
    const tk = getToken();
    if (!tk) { const e = new Error('未登录：缺少 authToken'); e.code = 401; throw e; }
    const r = await fetch('/api/presets/list', {
      headers: { 'X-App-Platform': 'web', 'Authorization': 'Bearer ' + tk, 'Accept': 'application/json' },
      credentials: 'include',
    });
    const j = await r.json().catch(() => null);
    if (!j) throw new Error('预设接口返回异常 HTTP ' + r.status);
    return j;
  }

  // promptList 拍平成 markdown：marker 条目是运行时占位符，其余是真实系统提示词
  function presetsToMarkdown(json) {
    const list = (json && json.openai_settings) || [];
    const out = ['# aisese.ai 提示词预设导出', '', '> 导出时间 ' + new Date().toISOString(), ''];
    for (const p of list) {
      out.push('---', '', '# 预设：' + (p.name || p.id) + '  (`' + p.id + '`)');
      if (p.intro) out.push('> ' + p.intro);
      out.push('');
      for (const e of (p.promptList || [])) {
        out.push('## [' + (e.identifier || '') + '] ' + (e.name || ''));
        out.push('- role=`' + (e.role || 'system') + '` marker=`' + !!e.marker + '` enabled=`' + (e.enabled !== false) + '`');
        out.push('');
        out.push(e.marker ? '（运行时替换：角色/用户/世界书/示例对话/聊天记录/作者笔记）' : (e.content || ''));
        out.push('');
      }
      const rx = p.regexList || [];
      if (rx.length) {
        out.push('## 正则脚本（' + rx.length + ' 条）', '');
        for (const x of rx) out.push('- `' + (x.scriptName || '') + '`  find=`' + (x.findRegex || '') + '`');
        out.push('');
      }
    }
    return out.join('\n');
  }

  async function exportPrompts() {
    ui.status('① 拉取提示词预设 …');
    const j = await fetchPresets();
    const md = presetsToMarkdown(j);
    const stamp = new Date().toISOString().slice(0, 10);
    await saveFile(new TextEncoder().encode(md), 'aisese-提示词预设-' + stamp + '.md', 'text/markdown');
    await sleep(300);
    await saveFile(new TextEncoder().encode(JSON.stringify(j, null, 2)), 'aisese-提示词预设-' + stamp + '.json', 'application/json');
    const sets = j.openai_settings || [];
    const first = (sets[0] || {}).promptList || [];
    const real = first.filter((e) => !e.marker && e.content).length;
    ui.status('✔ 已导出 ' + sets.length + ' 套预设；首套 ' + first.length + ' 条（其中 ' + real + ' 条是真实提示词）');
    return { json: j, md };
  }

  /* ============ 2. 归一化 ============ */
  const str = (v) => (v === undefined || v === null ? '' : typeof v === 'string' ? v : JSON.stringify(v));

  // attrs 是 [{key,value}]，很多卡 key 为空、靠顺序表示字段
  // 站点固定 10 槽位角色表单（无 key，靠下标语义）
  const ATTR_LABELS = ['姓名', '性别', '身高', '体重', '年龄', '职业', '', '性癖/身体反应', '性格/神态', '背景/人设'];

  function attrsToText(attrs) {
    if (!Array.isArray(attrs)) return '';
    return attrs
      .map((a, i) => {
        const k = str(a && a.key).trim() || ATTR_LABELS[i] || '';
        const v = str(a && a.value).trim();
        if (!v) return '';
        return k ? k + '：' + v : v;
      })
      .filter(Boolean)
      .join('\n');
  }

  function greetingsOf(data) {
    const g = (data.prologue && data.prologue.greetings) || [];
    if (!Array.isArray(g)) return [];
    return g.map((x) => str(x && x.value)).filter((s) => s.trim());
  }

  function toCharacterBook(data) {
    const books = data.characterbooks || [];
    if (!Array.isArray(books) || !books.length) return null;
    const entries = [];
    for (const b of books) {
      const list = (b && b.entryList) || [];
      for (const e of list) {
        const content = str(e && e.content);
        if (!content.trim()) continue;
        const kw = str(e && e.triggerKeywords);
        entries.push({
          keys: kw.split(/[,，\n]/).map((s) => s.trim()).filter(Boolean),
          content,
          extensions: {},
          enabled: e.enabled !== false,
          insertion_order: Number(e.depth) || entries.length,
          case_sensitive: false,
          name: str(e.name) || str(b.name) || '条目 ' + (entries.length + 1),
          priority: Number(e.role) || 10,
          id: entries.length,
          comment: '',
          selective: !!e.recursiveScan,
          secondary_keys: [],
          constant: !!e.constant,
          position: Number(e.position) === 4 ? 'after_char' : 'before_char',
        });
      }
    }
    if (!entries.length) return null;
    return { name: str(books[0].name) || '世界书', entries, extensions: {} };
  }

  /* ============ 3. 组装 CCv2 / CCv3 ============ */
  function buildV2(data) {
    const ch = (data.charList && data.charList[0]) || {};
    const greetings = greetingsOf(data);
    const attrsText = attrsToText(ch.attrs);
    const customText = Array.isArray(ch.customAttrs)
      ? ch.customAttrs.map((a) => (a && a.label ? a.label + '：' + str(a.value) : '')).filter(Boolean).join('\n')
      : '';
    const promptText = str(ch.prompt).trim();
    const fineTune = str(data.prompts && data.prompts.characterFineTunePrompt).trim();
    const genPrompt = str(data.prompts && data.prompts.characterGenerationPrompt).trim();

    // 真正的角色设定：优先 prompt，其次 attrs，再补 fineTune / customAttrs
    const parts = [];
    if (promptText) parts.push(promptText);
    if (attrsText) parts.push(attrsText);
    if (customText) parts.push(customText);
    if (fineTune) parts.push(fineTune);
    const description = parts.join('\n\n') || str(ch.intro) || str(data.intro);

    const book = toCharacterBook(data);
    const v2 = {
      name: str(data.name) || str(ch.name) || '未命名角色',
      description,
      personality: '',
      scenario: '',
      first_mes: greetings[0] || '',
      mes_example: genPrompt,
      creator_notes: str(data.intro),
      system_prompt: '',
      post_history_instructions: '',
      alternate_greetings: greetings.slice(1),
      tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
      creator: str(data.authorName) || str(data.author),
      character_version: '1.0',
      extensions: {
        talkativeness: '0.5',
        fav: false,
        world: book ? book.name : '',
        aisese: {
          sid: str(data.sid),
          id: data.id || null,
          authorHandle: str(data.authorHandle),
          cover: str(data.cover),
          baseTokenCount: data.baseTokenCount || null,
          ageRating: str(data.ageRating),
          gender: str(data.gender),
          type: str(data.type),
          subType: str(data.subType),
          greetingsCount: greetings.length,
          booksCount: (data.characterbooks || []).length,
          source: 'aisese.ai',
          exported_at: new Date().toISOString(),
        },
        aisese_raw: data,
      },
    };
    if (book) v2.character_book = book;
    return v2;
  }

  function toV3(v2) {
    const d = JSON.parse(JSON.stringify(v2));
    d.group_only_greetings = [];
    d.creation_date = Math.floor(Date.now() / 1000);
    d.modification_date = d.creation_date;
    d.creator_notes_multilingual = {};
    d.source = ['aisese.ai'];
    d.assets = [];
    return { spec: 'chara_card_v3', spec_version: '3.0', data: d };
  }

  /* ============ 4. PNG tEXt 写入（与酒馆解析逻辑对齐） ============ */
  const CRC_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; }
    return t;
  })();
  function crc32(bytes) {
    let c = 0xffffffff;
    for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  }
  const concatBytes = (arrs) => {
    const total = arrs.reduce((n, a) => n + a.length, 0);
    const out = new Uint8Array(total);
    let off = 0;
    for (const a of arrs) { out.set(a, off); off += a.length; }
    return out;
  };
  function u32(n) { const b = new Uint8Array(4); new DataView(b.buffer).setUint32(0, n >>> 0); return b; }
  function b64utf8(s) {
    const bytes = new TextEncoder().encode(s);
    let bin = '';
    const CH = 0x8000;
    for (let i = 0; i < bytes.length; i += CH) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));
    return btoa(bin);
  }
  function makeTextChunk(keyword, text) {
    const k = new TextEncoder().encode(keyword);
    const t = new TextEncoder().encode(text);
    const data = new Uint8Array(k.length + 1 + t.length);
    data.set(k, 0); data[k.length] = 0; data.set(t, k.length + 1);
    return { type: 'tEXt', data };
  }
  function parsePngChunks(buf) {
    const chunks = [];
    let off = 8;
    while (off + 8 <= buf.length) {
      const len = new DataView(buf.buffer, buf.byteOffset + off, 4).getUint32(0);
      const type = String.fromCharCode(buf[off + 4], buf[off + 5], buf[off + 6], buf[off + 7]);
      chunks.push({ type, data: buf.slice(off + 8, off + 8 + len) });
      off += 12 + len;
      if (type === 'IEND') break;
    }
    return chunks;
  }
  function buildPng(chunks) {
    const parts = [new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])];
    for (const c of chunks) {
      const tb = new TextEncoder().encode(c.type);
      parts.push(u32(c.data.length), tb, c.data, u32(crc32(concatBytes([tb, c.data]))));
    }
    return concatBytes(parts);
  }
  function embedCard(pngBytes, v2, v3) {
    let chunks = parsePngChunks(pngBytes).filter((c) => {
      if (c.type !== 'tEXt') return true;
      const kw = String.fromCharCode.apply(null, c.data.slice(0, Math.min(8, c.data.length))).split('\u0000')[0].toLowerCase();
      return kw !== 'chara' && kw !== 'ccv3';
    });
    const at = Math.max(1, chunks.findIndex((c) => c.type === 'IHDR') + 1);
    chunks.splice(at, 0,
      makeTextChunk('chara', b64utf8(JSON.stringify(v2))),
      makeTextChunk('ccv3', b64utf8(JSON.stringify(v3))),
    );
    return buildPng(chunks);
  }

  /* ============ 5. 图片与保存 ============ */
  async function fetchImageBytes(candidates) {
    for (const u of candidates) {
      if (!u) continue;
      try {
        const r = await fetch(u, { mode: 'cors', credentials: 'include' });
        if (!r.ok) continue;
        const b = new Uint8Array(await r.arrayBuffer());
        // png / webp / jpeg 都收，非 PNG 交给 canvas 转码
        if (b.length > 12 && /^image\//.test(r.headers.get('content-type') || '')) return b;
      } catch (e) { /* 试下一个 */ }
    }
    return null;
  }

  async function toPngBytes(raw) {
    if (!raw) return null;
    if (raw[0] === 0x89 && raw[1] === 0x50) return raw;
    // JPEG → 画到 canvas 转 PNG（canvas 产出的 PNG 不带脏数据，可安全写块）
    try {
      const blob = new Blob([raw]);
      const bmp = await createImageBitmap(blob);
      const c = document.createElement('canvas');
      c.width = bmp.width; c.height = bmp.height;
      c.getContext('2d').drawImage(bmp, 0, 0);
      const out = await new Promise((res) => c.toBlob(res, 'image/png'));
      return new Uint8Array(await out.arrayBuffer());
    } catch (e) { return null; }
  }

  async function makePlaceholderPng(text) {
    const c = document.createElement('canvas');
    c.width = 400; c.height = 600;
    const g = c.getContext('2d');
    const grad = g.createLinearGradient(0, 0, 400, 600);
    grad.addColorStop(0, '#1b2430'); grad.addColorStop(1, '#2f4a63');
    g.fillStyle = grad; g.fillRect(0, 0, 400, 600);
    g.fillStyle = '#e8f0f8'; g.font = 'bold 24px sans-serif'; g.textAlign = 'center';
    g.fillText(String(text || '角色卡').slice(0, 14), 200, 300);
    g.font = '15px sans-serif'; g.fillStyle = '#9db4c8';
    g.fillText('aisese.ai', 200, 336);
    const blob = await new Promise((res) => c.toBlob(res, 'image/png'));
    return new Uint8Array(await blob.arrayBuffer());
  }

  const IS_MOBILE = /Android|iPhone|iPad|iPod|HarmonyOS|Mobile/i.test(navigator.userAgent) ||
    (navigator.maxTouchPoints > 1 && /Macintosh/i.test(navigator.userAgent));

  function download(bytes, filename, mime) {
    const blob = new Blob([bytes], { type: mime || 'application/octet-stream' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
  }

  async function saveFile(bytes, filename, mime) {
    if (IS_MOBILE && navigator.canShare) {
      try {
        const file = new File([new Blob([bytes], { type: mime })], filename, { type: mime });
        if (navigator.canShare({ files: [file] })) { await navigator.share({ files: [file], title: filename }); return 'shared'; }
      } catch (e) { if (e && e.name === 'AbortError') return 'aborted'; }
    }
    download(bytes, filename, mime);
    return 'downloaded';
  }

  const sanitize = (s) => String(s || 'character').replace(/[\\/:*?"<>|\r\n\t]/g, '_').slice(0, 60);

  /* ============ 6. 主流程 ============ */
  async function exportCard(input, opts) {
    const o = Object.assign({ png: true, json: true }, opts || {});
    const sid = parseSid(input);
    if (!sid) throw new Error('无法解析卡片 sid：' + input);

    ui.status('① 拉取卡片 …');
    const data = await fetchCard(sid);

    const v2 = buildV2(data);
    const card = { spec: 'chara_card_v2', spec_version: '2.0', data: v2 };
    const v3 = toV3(v2);
    const base = sanitize(v2.name);

    if (o.png) {
      ui.status('② 合成 PNG 卡片 …');
      const origin = location.origin;
      const cover = str(data.cover);
      // 实测：封面在 studio-images.aisese.ai，但该域**无 Access-Control-Allow-Origin**，
      // 浏览器 fetch 被拒、<img> 画进 canvas 会被污染 → 封面永远读不到字节。
      // 作者头像在 static.aisese.ai，带 ACAO:*，可读可转码。
      // 顺序：封面（大概率失败）→ 作者头像 → 占位图
      const avatar = str(data.authorAvatar);
      const cands = [];
      if (/^https?:/.test(cover)) cands.push(cover);
      else if (cover) cands.push('https://studio-images.aisese.ai/' + cover, origin + '/' + cover);
      if (avatar) cands.push(/^https?:/.test(avatar) ? avatar : 'https://static.aisese.ai/upload_user_avatar/' + avatar);
      const raw = await fetchImageBytes(cands);
      const pngImg = (await toPngBytes(raw)) || (await makePlaceholderPng(v2.name));
      const png = embedCard(pngImg, card, v3);
      await saveFile(png, base + '.png', 'image/png');
      await sleep(350);
    }
    if (o.json) {
      await saveFile(new TextEncoder().encode(JSON.stringify(card, null, 2)), base + '.json', 'application/json');
      await sleep(350);
      await saveFile(new TextEncoder().encode(JSON.stringify(v3, null, 2)), base + '.v3.json', 'application/json');
    }

    ui.status('✔ ' + v2.name + '｜设定 ' + v2.description.length + ' 字｜开场白 ' + v2.first_mes.length +
      ' 字｜备选 ' + v2.alternate_greetings.length + ' 条｜世界书 ' +
      (v2.character_book ? v2.character_book.entries.length : 0) + ' 条');
    LOG('导出完成', { name: v2.name, description: v2.description.length, first_mes: v2.first_mes.length });
    return { card, v3, data };
  }

  /* ============ 7. UI ============ */
  const ui = {
    status(msg) {
      const el = document.getElementById('ase-status');
