    var cur = relayBase();
    var val = window.prompt('中转地址（和点歌台填同一个，留空则清空）', cur);
    if (val === null) return;
    var v = String(val).trim().replace(/\/+$/, '');
    if (v && !/^https?:\/\//i.test(v)) {
      setStat('要以 http(s):// 开头');
      return;
    }
    lsSet(LS.relay, v);
    diag.relay = v;
    setStat(v ? '已保存中转地址' : '已清空中转地址');
    render();
  }

